{
  "questions": [
    {
      "index": 4,
      "slo_id": "S4",
      "level": "understand",
      "question": "Which of these statements is true for a proper fraction?",
      "options": [
        "The numerator is smaller than the denominator.",
        "The numerator is bigger than the denominator.",
        "The fraction is equal to one whole."
      ],
      "correct_index": 0,
      "explanation": "In a proper fraction, the numerator is always smaller than the denominator, meaning its value is less than one whole.",
      "selected_because": "the definition of a proper fraction",
      "distractor_misconceptions": {
        "1": "confuses proper fraction with improper fraction",
        "2": "thinks proper fraction means it equals one whole"
      },
      "option_feedback": {
        "correct": "That's right! For a proper fraction, the top number (numerator) is always smaller than the bottom number (denominator).",
        "wrong": {
          "1": "This describes an improper fraction, not a proper fraction. Remember, for a proper fraction like $\\frac{2}{5}$, the numerator (2) is smaller than the denominator (5).",
          "2": "A proper fraction is always less than one whole. When a fraction is equal to one whole, like $\\frac{4}{4}$, it's not a proper fraction."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "In all of these the top number is smaller than the bottom number, so the value of the fraction is less than one whole.",
      "teaching_error": null
    },
    {
      "index": 6,
      "slo_id": "S6",
      "level": "apply",
      "question": "What is $\\frac{7}{3}$ as a mixed number?",
      "options": [
        "$2\\frac{1}{3}$",
        "$1\\frac{2}{3}$",
        "$3\\frac{1}{3}$"
      ],
      "correct_index": 0,
      "explanation": "To convert an improper fraction to a mixed number, divide the numerator by the denominator. The quotient is the whole number, and the remainder is the new numerator over the original denominator.",
      "selected_because": "converting an improper fraction to a mixed number",
      "distractor_misconceptions": {
        "1": "incorrectly calculates the whole number part",
        "2": "incorrectly calculates the remainder or whole number"
      },
      "option_feedback": {
        "correct": "Excellent! When you divide 7 by 3, you get 2 with a remainder of 1, so $\\frac{7}{3}$ is $2\\frac{1}{3}$.",
        "wrong": {
          "1": "Not quite. When you divide 7 by 3, the whole number part is 2, not 1. You have 2 full groups of 3 in 7, with 1 left over.",
          "2": "Let's recheck the division. 7 divided by 3 is 2 with a remainder of 1, so the whole number is 2 and the fraction is $\\frac{1}{3}$."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Fractions like seven over four, nine over five as improper fractions.",
      "teaching_error": null
    }
  ]
}
